WITH airport_stats AS (SELECT OriginCode, any(OriginCityName) AS OriginCityName, count() AS completed_departures, round(avg(DepDel15 = 0), 4) AS on_time_performance, round(avg(DepDelay), 2) AS avg_departure_delay, round(quantile(0.90)(DepDelay), 2) AS p90_departure_delay, min(FlightDate) AS first_date, max(FlightDate) AS last_date FROM ontime.fact_ontime WHERE Cancelled = 0 GROUP BY OriginCode HAVING completed_departures >= 100000), ranked_airports AS (SELECT *, row_number() OVER (ORDER BY on_time_performance ASC) AS rnk, count() OVER () AS total_airports FROM airport_stats) SELECT * FROM ranked_airports WHERE rnk = 1 OR rnk = intDiv(total_airports, 2)
